DROP TABLE IF EXISTS `skill_evidence`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `skill_evidence` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `repository_id` int unsigned NOT NULL,
  `skill_name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `evidence_type` varchar(60) COLLATE utf8mb4_unicode_ci NOT NULL,
  `evidence_details` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `evidence_file_path` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `confidence_score` decimal(5,2) DEFAULT NULL,
  `detected_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_skill_evidence_repo_skill` (`repository_id`,`skill_name`),
  KEY `idx_skill_evidence_skill_name` (`skill_name`),
  CONSTRAINT `fk_skill_evidence_repository_id` FOREIGN KEY (`repository_id`) REFERENCES `repositories` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=765 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
